import {TASKS,AUX,HEAT_METHODS,MATERIAL_UNITS,LEVELS,STATUSES,uid,makeZone,makePlan,active,summarize,validatePlan,migratePlan,zoneTasks,setEquipment,materialLedger} from './concept-model.mjs';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='steel-concept-studio-v1';
let plans=[makePlan(true)],current=plans[0].id,selected=plans[0].zones[0].id,equipment=[],examples=[],editorTab='function',storageProblem=false,dragged=null,removed=null;
try{const stored=JSON.parse(localStorage.getItem(KEY));if(stored?.version===1&&Array.isArray(stored.plans)&&stored.plans.length){stored.plans.forEach(validatePlan);plans=stored.plans;current=plans.some(x=>x.id===stored.current)?stored.current:plans[0].id;selected=plan().zones[0]?.id;}}catch{storageProblem=true;}
function plan(){return plans.find(x=>x.id===current);}function zone(){return plan().zones.find(x=>x.id===selected);}
function save(){try{localStorage.setItem(KEY,JSON.stringify({version:1,current,plans}));$('#save-status').textContent='已保存';}catch{$('#save-status').textContent='请导出备份：本地保存不可用';}}
function opts(values,value){return values.map(x=>{const [id,label]=Array.isArray(x)?x:[x,x];return `<option value="${esc(id)}" ${id===value?'selected':''}>${esc(label)}</option>`;}).join('');}
function text(id,label,value,area=false){return `<label>${label}${area?`<textarea id="${id}">${esc(value)}</textarea>`:`<input id="${id}" value="${esc(value)}">`}</label>`;}
function range(id,label,value,max,step=1,unit='',min=0){return `<label>${label} <output id="${id}-value">${value===null?'未填':esc(value)+' '+unit}</output><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value??min}"></label><button class="clear" data-clear="${id}">清空</button>`;}
function bindRange(id,object,key,callback=()=>{}){const el=$('#'+id);el.oninput=()=>{object[key]=Number(el.value);$('#'+id+'-value').textContent=el.value;save();drawFlow();callback();};document.querySelector(`[data-clear="${id}"]`).onclick=()=>{object[key]=null;save();drawFlow();drawEditor();};}
function drawBrief(){const p=plan();$('#brief').innerHTML=text('plan-name','方案名称',p.name)+text('feed','来料与流量范围',p.feed,true)+text('product','目标产品与指标',p.product,true)+text('idea','核心构想',p.idea,true);for(const k of ['name','feed','product','idea'])$('#'+(k==='name'?'plan-name':k)).onchange=e=>{p[k]=e.target.value.slice(0,k==='name'?200:10000)||(k==='name'?'未命名构想':'');save();drawPlans();};}
function drawPlans(){$('#plans').innerHTML=opts(plans.map(x=>[x.id,x.name]),current);}
function add(task,lane='main',anchor=null){const z=makeZone(task);z.lane=lane;z.anchor=anchor;const ref=equipment.find(e=>e.equipment_id===z.reference);if(ref){z.effect=equipmentEffect(ref);z.supplyNote=SUPPLY_FALLBACK(z.reference);}plan().zones.push(z);selected=z.id;editorTab='function';save();render();}
function SUPPLY_FALLBACK(ref){const sample=makeZone();setEquipment(sample,ref,'');return sample.supplyNote;}
function equipmentEffect(e){return e?.equipment_id==='RH'?'脱碳、脱气、合金化／成分微调':e?.functions||'';}
function drawCatalog(){const q=$('#search').value.trim().toLowerCase();$('#catalog').innerHTML=TASKS.filter(t=>(t.name+t.refs.join(' ')+t.question).toLowerCase().includes(q)).map(t=>`<button class="task" data-task="${t.id}"><strong>＋ ${t.name}</strong><small>${t.refs.join(' / ')||'自由添加'}</small></button>`).join('');$('#catalog').querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>{const z=zone(),use=$('#add-place').value==='selected'&&z;add(b.dataset.task,use?z.lane:'main',use?z.anchor:null);});}
function removeZone(id){const i=plan().zones.findIndex(z=>z.id===id);if(i<0)return;removed={plan:current,zone:plan().zones[i],index:i};plan().zones.splice(i,1);if(selected===id)selected=plan().zones[Math.max(0,i-1)]?.id;save();drawFlow();drawEditor();$('#undo').hidden=false;}
function move(id,delta){const list=plan().zones,z=list.find(x=>x.id===id),siblings=list.filter(x=>x.lane===z.lane&&x.anchor===z.anchor),target=siblings[siblings.indexOf(z)+delta];if(!target)return;const a=list.indexOf(z),b=list.indexOf(target);[list[a],list[b]]=[list[b],list[a]];save();drawFlow();}
function place(id,targetId,lane,anchor){const list=plan().zones,z=list.find(x=>x.id===id),target=list.find(x=>x.id===targetId);if(!z||z===target)return;z.lane=target?target.lane:lane;z.anchor=z.lane==='main'?null:(target?target.anchor:anchor);if(z.anchor===z.id)z.anchor=null;if(z.lane==='side'&&z.flowFactor>1)z.flowFactor=null;list.splice(list.indexOf(z),1);list.splice(target?list.indexOf(target):list.length,0,z);selected=z.id;save();drawFlow();drawEditor();}
function drawFlow(){const p=plan(),s=summarize(p);const card=z=>`<div class="zone-wrap" draggable="true" data-drag="${esc(z.id)}" data-drop="${esc(z.id)}"><div class="zone-tools"><button data-move="${esc(z.id)}" data-delta="-1" aria-label="向前移动 ${esc(z.name)}">←</button><span>拖动移动</span><button data-move="${esc(z.id)}" data-delta="1" aria-label="向后移动 ${esc(z.name)}">→</button><button class="danger" data-remove="${esc(z.id)}" aria-label="删除 ${esc(z.name)}">×</button></div><button class="zone ${z.id===selected?'selected':''}" data-zone="${esc(z.id)}" style="width:${128+z.length*18}px"><span class="aux top">${esc(z.aux.filter(x=>!/(补热|冷却|测温|在线)/.test(x)).join(' · '))}</span><strong>${esc(z.name)}</strong><small class="task-badges">${zoneTasks(z).map(t=>esc(TASKS.find(x=>x.id===t)?.name||t)).join(' · ')}</small><small>${z.length.toFixed(1)} m · ${esc(z.reference||'自定义')}</small><span class="aux bottom">${esc(z.heating.map(h=>h.method+(h.hold===null?'':` / 补偿 ${h.hold}℃`)).join(' · '))}</span></button></div>`;
 const groups=new Map();for(const z of s.other){const key=z.lane+'|'+z.anchor;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(z);}
 $('#flow').innerHTML=`<div class="lane-wrap"><div class="lane" data-lane="main"><div class="terminal">电炉<br>出钢口</div><span class="connector"></span>${s.main.map(z=>card(z)+'<span class="connector"></span>').join('')}<div class="terminal">出口<br>连铸机</div></div></div>${[...groups.values()].map((list,i)=>{const z=list[0],a=s.main.find(x=>x.id===z.anchor);return `<div class="branch"><div class="section-head"><strong>${z.lane==='cycle'?'循环':'旁路'} · ${a?esc(a.name):'选择连接区'}</strong><button data-add-branch="${i}">＋ 添加精炼模块</button></div><div class="lane-wrap"><div class="lane branch-lane">${list.map(x=>card(x)+'<span class="connector"></span>').join('')}</div></div></div>`;}).join('')}<div class="drop-new" data-new-side>拖入模块以新建旁路，或在右侧修改路径</div>${p.zones.filter(z=>!active(z)).length?`<details><summary>暂缓／淘汰模块</summary>${p.zones.filter(z=>!active(z)).map(z=>`<button data-zone="${esc(z.id)}">${esc(z.name)}</button><button data-remove="${esc(z.id)}" class="danger">删除</button>`).join(' ')}</details>`:''}`;
 $('#flow').querySelectorAll('[data-zone]').forEach(b=>b.onclick=()=>{selected=b.dataset.zone;drawFlow();drawEditor();});
 $('#flow').querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>removeZone(b.dataset.remove));
 $('#flow').querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>move(b.dataset.move,Number(b.dataset.delta)));
 $('#flow').querySelectorAll('[data-drag]').forEach(el=>{el.ondragstart=e=>{dragged=el.dataset.drag;e.dataTransfer.setData('text/plain',dragged);e.dataTransfer.effectAllowed='move';};el.ondragend=()=>{dragged=null;document.querySelectorAll('.drop-over').forEach(x=>x.classList.remove('drop-over'));};el.ondragover=e=>{if(dragged){e.preventDefault();el.classList.add('drop-over');}};el.ondragleave=()=>el.classList.remove('drop-over');el.ondrop=e=>{e.preventDefault();e.stopPropagation();place(dragged,el.dataset.drop);};});
 const end=$('[data-lane="main"]');end.ondragover=e=>{if(dragged)e.preventDefault();};end.ondrop=e=>{e.preventDefault();place(dragged,null,'main',null);};
 const side=$('[data-new-side]');side.ondragover=e=>{if(dragged)e.preventDefault();};side.ondrop=e=>{e.preventDefault();const anchor=s.main.find(x=>x.id===selected&&x.id!==dragged)||s.main.find(x=>x.id!==dragged);place(dragged,null,'side',anchor?.id||null);};
 $('#flow').querySelectorAll('[data-add-branch]').forEach(b=>b.onclick=()=>{const z=[...groups.values()][Number(b.dataset.addBranch)][0];add('custom',z.lane,z.anchor);});
 $('#overview').innerHTML=`<div class="metrics"><div class="metric"><strong>${s.zones.length}</strong><span>功能区</span></div><div class="metric"><strong>${s.mainLength.toFixed(1)} m</strong><span>主流布局长度</span></div><div class="metric"><strong>${s.otherLength.toFixed(1)} m</strong><span>支路／循环长度</span></div></div><div class="coverage">${TASKS.filter(t=>t.id!=='custom').map(t=>`<span class="tag ${s.tasks.includes(t.id)?'on':''}">${s.tasks.includes(t.id)?'✓ ':''}${t.name}</span>`).join('')}</div>`;
 const questions=s.zones.filter(z=>z.question.trim());$('#review').innerHTML=`<div><h3>组合关系</h3><ul>${s.issues.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div><h3>研究问题</h3><ol>${questions.map(z=>`<li><strong>${esc(z.name)}</strong>：${esc(z.question)}</li>`).join('')}</ol></div>`;
 drawLedgers(s);
}
function drawLedgers(s){const rows=materialLedger(plan());$('#materials-summary').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>投入物料／能源</th><th>每吨总来料合计</th><th>使用模块</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.name)}<div class="muted">${r.notes.map(esc).join("<br>")}</div></td><td>${r.missing?`待补齐（已知部分 ${r.known.toLocaleString('zh-CN',{maximumSignificantDigits:6})}）`:r.known.toLocaleString('zh-CN',{maximumSignificantDigits:6})} ${esc(r.unit)}</td><td>${r.contributors.map(esc).join('、')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">在右侧「气体与物料」添加气体、粉剂、合金或电耗，自动汇总每吨投入。</p>';
 $('#thermal-summary').innerHTML=s.zones.some(z=>z.heating.length)?`<div class="table-wrap"><table><thead><tr><th>功能区／方式</th><th>目标保温／补偿温降</th><th>效率记录</th><th>设备与功率备注</th></tr></thead><tbody>${s.zones.flatMap(z=>z.heating.map(h=>`<tr><td>${esc(z.name)}／${esc(h.method)}</td><td>${h.target===null?'保温待填':h.target+' ℃'}／${h.hold===null?'补偿待填':h.hold+' ℃'}</td><td>${h.eta===null?'待填':h.eta+' %'}</td><td>${h.power===null?'功率待填':h.power+' kW'} ${esc(h.note)}</td></tr>`)).join('')}</tbody></table></div><p class="muted">以上为手工规划记录，同一区的多种方式并列展示，不叠加温度、不反算热效率。</p>`:'<p class="muted">在右侧「补热记录」多选设备，暂记希望补偿的温降、功率与效率。</p>';
}
function drawEditor(){const z=zone();if(!z){$('#editor').innerHTML='<h2>选择功能区</h2><p>从左侧添加，或点击画板中的模块。</p>';return;}
 const main=plan().zones.filter(x=>active(x)&&x.lane==='main'&&x.id!==z.id);
 $('#editor').innerHTML=`<div class="section-head"><h2>${esc(z.name)}</h2><button id="delete" class="danger">删除功能区</button></div><div class="editor-tabs">${[['function','功能与能力'],['supply','气体与物料'],['heat','补热记录'],['notes','补充']].map(([id,label])=>`<button data-tab="${id}" aria-pressed="${editorTab===id}">${label}</button>`).join('')}</div><div id="editor-fields"></div>`;
 $('#delete').onclick=()=>removeZone(z.id);$('#editor').querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{editorTab=b.dataset.tab;drawEditor();});
 const fields=$('#editor-fields');
 if(editorTab==='function'){
 fields.innerHTML=text('z-name','模块名称',z.name)+`<label>设备<select id="z-reference">${opts([['','自定义／暂未选'],...equipment.map(e=>[e.equipment_id,`${e.equipment_id} · ${e.name}`])],z.reference)}</select></label>`+text('z-effect','方式效果',z.effect,true)+`<fieldset><legend>叠加精炼任务（可多选）</legend>${TASKS.filter(x=>x.id!=='custom').map(t=>`<label><input type="checkbox" data-task-check="${t.id}" ${zoneTasks(z).includes(t.id)?'checked':''}> ${t.name}</label>`).join('')}</fieldset>`+text('z-capability','能力补充：脱气、合金化等具体要求',z.capability,true)+`<label>布置路径<select id="z-lane">${opts([['main','连续主流'],['side','旁路'],['cycle','循环']],z.lane)}</select></label>${z.lane!=='main'?`<label>连接主流区<select id="z-anchor">${opts([['','待选择'],...main.map(x=>[x.id,x.name])],z.anchor||'')}</select></label>`:''}<label>占用长度 <output id="length-label">${z.length.toFixed(1)} m</output><input id="z-length" type="range" min="0.5" max="3" step="0.5" value="${z.length}"></label><div class="actions"><button id="duplicate">复制此模块</button></div>`;
 for(const k of ['name','effect','capability','lane','anchor'])$('#z-'+k)?.addEventListener('change',e=>{z[k]=k==='anchor'?(e.target.value||null):e.target.value.slice(0,10000);if(k==='lane'&&z.lane==='main')z.anchor=null;if(k==='lane'&&z.lane==='side'&&z.flowFactor>1)z.flowFactor=null;save();drawFlow();if(['lane','anchor'].includes(k))drawEditor();});
 $('#z-reference').onchange=e=>{const ref=equipment.find(x=>x.equipment_id===e.target.value),old=equipment.find(x=>x.equipment_id===z.reference);if(!z.name||z.name===old?.name||z.name===TASKS.find(t=>t.id===z.task)?.name||z.name==='自定义构想')z.name=ref?.name||'自定义构想';setEquipment(z,e.target.value,equipmentEffect(ref));save();drawFlow();drawEditor();};
 $('#editor').querySelectorAll('[data-task-check]').forEach(c=>c.onchange=()=>{z.tasks=c.checked?[...new Set([...z.tasks.filter(t=>t!=='custom'),c.dataset.taskCheck])]:z.tasks.filter(t=>t!==c.dataset.taskCheck);if(!z.tasks.length)z.tasks=['custom'];z.task=z.tasks[0];save();drawFlow();});
 $('#z-length').oninput=e=>{z.length=Number(e.target.value);$('#length-label').textContent=z.length.toFixed(1)+' m';save();drawFlow();};
 $('#duplicate').onclick=()=>{const copy=structuredClone(z);copy.id=uid();copy.name+=' · 副本';plan().zones.splice(plan().zones.indexOf(z)+1,0,copy);selected=copy.id;save();drawFlow();drawEditor();};
 }else if(editorTab==='supply')drawSupply(z,fields);
 else if(editorTab==='heat')drawHeat(z,fields);
 else{fields.innerHTML=`<label>筛选状态<select id="z-status">${opts(STATUSES,z.status)}</select></label><label>证据记录<select id="z-level">${opts(LEVELS,z.level)}</select></label>`+text('z-evidence','来源编号／支持材料',z.evidence,true)+text('z-question','研究问题',z.question,true);for(const k of ['status','level','evidence','question'])$('#z-'+k).onchange=e=>{z[k]=e.target.value.slice(0,10000);save();drawFlow();};}
}
function drawSupply(z,fields){const matching=examples.filter(x=>z.reference==='VD'?x.process==='VD':z.reference==='LF'?x.process.includes('LF'):false);
 fields.innerHTML=text('z-supply','气体、喷粉与辅料备注',z.supplyNote,true)+`<details><summary>辅助方式多选</summary><fieldset>${AUX.map((a,i)=>`<label><input type="checkbox" data-aux="${i}" ${z.aux.includes(a)?'checked':''}> ${a}</label>`).join('')}</fieldset></details><div class="section-head"><h3>每吨处理钢水的投入</h3><button id="add-material">＋ 物料</button></div><p class="muted">粉／合金用 kg/t；气体注明体积基准。空白不计作零。</p>${z.lane!=='main'?range('flow-factor','该模块处理量／总来料量',z.flowFactor,z.lane==='side'?1:5,.05,'倍')+'<p class="muted">用于换算整床物耗；循环可大于 1，旁路按实际分流填写。</p>':''}<div id="material-rows">${z.materials.map((m,i)=>`<section class="record"><div class="section-head"><strong>物料 ${i+1}</strong><button data-mremove="${i}" class="danger">删除</button></div>${text('m-name-'+i,'名称',m.name)}<label>用途<select id="m-role-${i}">${opts(['投入','过程产出','备注'],m.role)}</select></label><label>单位<select id="m-unit-${i}">${opts(MATERIAL_UNITS,m.unit)}</select></label>${range('m-amount-'+i,'每吨用量',m.amount,m.unit==='kg/t'?100:m.unit==='kWh/t'?500:10,m.unit==='kg/t'?.1:.001,m.unit)}${text('m-note-'+i,'用途／气体基准／能力备注',m.note,true)}</section>`).join('')}</div>${matching.length?`<details><summary>从数据包添加参考案例</summary><p class="muted">按原案例保留，点击后才加入物料表。</p>${matching.map((x,i)=>`<button class="example" data-example="${i}">${esc(x.observation_id)} · ${esc(x.parameter)}<br>${x.value.toFixed(4)} ${esc(x.unit)} · ${esc(x.case_id)}</button>`).join('')}</details>`:''}`;
 const presets=[['Ar','Nm³/t','投入'],['O₂','Nm³/t','投入'],['N₂','Nm³/t','投入'],['CO','Nm³/t','过程产出'],['CO₂','Nm³/t','过程产出'],['粉剂','kg/t','投入'],['合金料','kg/t','投入'],['石灰','kg/t','投入'],['电耗','kWh/t','投入']];
 $('#add-material').closest('.section-head').insertAdjacentHTML('afterend',`<div class="material-presets">${presets.map((x,i)=>`<button data-preset="${i}">＋ ${x[0]}</button>`).join('')}</div>`);
 $('#editor').querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{const [name,unit,role]=presets[Number(b.dataset.preset)];z.materials.push({id:uid(),name,unit,role,amount:null,note:role==='过程产出'?'按实际作用可改为投入；当前不计入消耗':''});save();drawFlow();drawEditor();});
 $('#z-supply').onchange=e=>{z.supplyNote=e.target.value.slice(0,10000);save();};
 $('#editor').querySelectorAll('[data-aux]').forEach(c=>c.onchange=()=>{const a=AUX[Number(c.dataset.aux)];z.aux=c.checked?[...z.aux,a]:z.aux.filter(x=>x!==a);save();drawFlow();});
 if(z.lane!=='main')bindRange('flow-factor',z,'flowFactor');
 $('#add-material').onclick=()=>{z.materials.push({id:uid(),name:'',role:'投入',unit:'kg/t',amount:null,note:''});save();drawEditor();};
 z.materials.forEach((m,i)=>{for(const k of ['name','role','unit','note'])$('#m-'+k+'-'+i).onchange=e=>{m[k]=e.target.value.slice(0,k==='name'?1000:10000);save();drawFlow();if(k==='unit')drawEditor();};bindRange('m-amount-'+i,m,'amount');});
 $('#editor').querySelectorAll('[data-mremove]').forEach(b=>b.onclick=()=>{z.materials.splice(Number(b.dataset.mremove),1);save();drawFlow();drawEditor();});
 $('#editor').querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{const x=matching[Number(b.dataset.example)],gas=x.parameter==='specific_argon_volume';z.materials.push({id:uid(),name:gas?'Ar':'石灰（'+x.quantity_role+'案例）',role:'投入',unit:x.unit==='Nm3/t'?'Nm³/t':x.unit==='m3_unspecified/t'?'m³/t（基准未定）':'kg/t',amount:x.value,note:`${x.observation_id} / ${x.source_id} / ${x.case_id} / ${x.process} / ${x.quantity_role}；${x.note||''}；原案例参考`});save();drawFlow();drawEditor();});
}
function drawHeat(z,fields){fields.innerHTML=`<fieldset><legend>选择补热／保温设备（可多选）</legend>${HEAT_METHODS.map((method,i)=>`<label><input type="checkbox" data-heat="${i}" ${z.heating.some(h=>h.method===method)?'checked':''}> ${method}</label>`).join('')}</fieldset>${z.heating.map((h,i)=>`<section class="record"><h3>${esc(h.method)}</h3>${range('h-target-'+i,'目标保温温度',h.target,1800,5,'℃',1400)}${range('h-hold-'+i,'目标补偿温降',h.hold,200,5,'℃')}${range('h-power-'+i,'设备功率',h.power,10000,50,'kW')}${range('h-eta-'+i,'暂记钢液有效热效率',h.eta,100,1,'%')}${text('h-note-'+i,'设备数量／布置／保温备注',h.note,true)}</section>`).join('')}<p class="muted">记录的是设计目标与假设值；有效热效率口径：钢液获得的净热量／设备输入能量。</p>`;
 $('#editor').querySelectorAll('[data-heat]').forEach(c=>c.onchange=()=>{const method=HEAT_METHODS[Number(c.dataset.heat)];if(c.checked)z.heating.push({method,hold:null,target:null,power:null,eta:null,note:''});else z.heating=z.heating.filter(h=>h.method!==method);save();drawFlow();drawEditor();});
 z.heating.forEach((h,i)=>{for(const k of ['target','hold','power','eta'])bindRange('h-'+k+'-'+i,h,k);$('#h-note-'+i).onchange=e=>{h.note=e.target.value.slice(0,10000);save();drawFlow();};});
}
function render(){drawPlans();drawBrief();drawCatalog();drawFlow();drawEditor();}
$('#search').oninput=drawCatalog;$('#plans').onchange=e=>{current=e.target.value;selected=plan().zones[0]?.id;removed=null;$('#undo').hidden=true;save();render();};
$('#new').onclick=()=>{const p=makePlan();plans.push(p);current=p.id;selected=null;save();render();};
$('#copy').onclick=()=>{const p=structuredClone(plan()),ids=new Map(p.zones.map(z=>[z.id,uid()]));p.id=uid();p.name+=' · 副本';p.zones.forEach(z=>{z.id=ids.get(z.id);z.anchor=ids.get(z.anchor)||null;});plans.push(p);current=p.id;selected=p.zones[0]?.id;save();render();};
$('#undo').onclick=()=>{if(removed?.plan!==current)return;plan().zones.splice(removed.index,0,removed.zone);selected=removed.zone.id;removed=null;$('#undo').hidden=true;save();render();};
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({format:'steel-concept-studio',version:1,plan:plan()},null,2)],{type:'application/json'}),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='refining-concept.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2000000)throw Error('文件超过 2 MB。');const d=JSON.parse(await f.text());if(d.format!=='steel-concept-studio'||d.version!==1)throw Error('不是受支持的概念方案文件。');const p=validatePlan(d.plan);p.id=uid();plans.push(p);current=p.id;selected=p.zones[0]?.id;save();render();}catch(err){$('#save-status').textContent='导入失败：'+err.message;}finally{e.target.value='';}};
function loadData(d){equipment=d.equipment;examples=d.observations.filter(x=>Number.isFinite(x.value)&&['kg/t','Nm3/t','m3_unspecified/t'].includes(x.unit));for(const p of plans)for(const z of p.zones){if(!z.effect)z.effect=equipmentEffect(equipment.find(e=>e.equipment_id===z.reference));if(!z.supplyNote)z.supplyNote=SUPPLY_FALLBACK(z.reference);}render();}
render();$('#save-status').textContent=storageProblem?'旧草稿未恢复，请检查备份':'编辑后自动保存';
if(typeof CONCEPT_DATA!=='undefined')loadData(CONCEPT_DATA);else fetch('./evidence/downloads/core-data.json').then(r=>{if(!r.ok)throw Error();return r.json();}).then(loadData).catch(()=>{$('#save-status').textContent='设备库载入失败，请重新打开页面';});
